// FindMany retrieves multiple Tenant records matching the filter
func (r *TenantRepository) FindMany(ctx context.Context, filter *TenantFilter, opts *TenantFindOptions) ([]*types.Tenant, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}

	// Build selected fields in OrderedMembers order so FK columns match scan order.
	var fieldStrings []string
	if opts.Fields.CreatedAt {
		fieldStrings = append(fieldStrings, "created_at")
	}
	if opts.Fields.UpdatedAt {
		fieldStrings = append(fieldStrings, "updated_at")
	}
	if opts.Fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if opts.Fields.Name {
		fieldStrings = append(fieldStrings, "name")
	}
	if opts.Fields.Slug {
		fieldStrings = append(fieldStrings, "slug")
	}
	if opts.Fields.Email {
		fieldStrings = append(fieldStrings, "email")
	}
	if opts.Fields.Status {
		fieldStrings = append(fieldStrings, "status")
	}
	if opts.Fields.IsActive {
		fieldStrings = append(fieldStrings, "is_active")
	}
	if opts.Fields.SeatCount {
		fieldStrings = append(fieldStrings, "seat_count")
	}
	if opts.Fields.Metadata {
		fieldStrings = append(fieldStrings, "metadata")
	}
	if opts.Fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	// hasMany hydration needs the parent primary key for child mapping.
	hasManyRequested := false
	if opts.Fields.UsersNested != nil {
		hasManyRequested = true
	}
	if hasManyRequested && !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}

	// Validate fields
	if err := validateFields(fieldStrings, TenantAllowedFields); err != nil {
		return nil, 0, err
	}

	// Build SELECT clause
	selectFields := buildSelectFieldsTyped(fieldStrings, "tenant")
	if selectFields == "" {
		return nil, 0, fmt.Errorf("no valid fields specified")
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildTenantOrderByClause(opts.OrderBy, "tenant")

	// Build LIMIT/OFFSET clause
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM tenant%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)

	// Get total count
	countQuery := fmt.Sprintf(`SELECT COUNT(*) FROM tenant%s`, whereClause)

	var totalCount int
	var countRow pgx.Row
	if r.tx != nil {
		countRow = r.tx.QueryRow(ctx, countQuery, args...)
	} else {
		countRow = r.db.pool.QueryRow(ctx, countQuery, args...)
	}
	if err := countRow.Scan(&totalCount); err != nil {
		return nil, 0, fmt.Errorf("failed to get count: %w", err)
	}

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, 0, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Tenant{}
	for rows.Next() {
		result := &types.Tenant{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempMetadata []byte

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)

		// Track whether special fields were selected so we can post-process after Scan.

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "created_at":
				scanDest[i] = &result.CreatedAt
			case "updated_at":
				scanDest[i] = &result.UpdatedAt
			case "id":
				scanDest[i] = &result.Id
			case "name":
				scanDest[i] = &result.Name
			case "slug":
				scanDest[i] = &result.Slug
			case "email":
				scanDest[i] = &result.Email
			case "status":
				scanDest[i] = &result.Status
			case "is_active":
				scanDest[i] = &result.IsActive
			case "seat_count":
				scanDest[i] = &result.SeatCount
			case "metadata":
				scanDest[i] = &tempMetadata
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, 0, fmt.Errorf("unexpected field %q for Tenant.FindMany", fieldName)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, 0, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if len(tempMetadata) > 0 {
			_ = unmarshalJSONFieldValue(tempMetadata, &result.Metadata)
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, 0, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)
	if opts.Fields.UsersNested != nil {
		childFields := *opts.Fields.UsersNested
		if childFields.IsZero() {
			childFields = TenantUserFields{Id: true}
		}
		childFieldsValue := reflect.ValueOf(&childFields).Elem()
		parentRelationFieldCandidates := []string{
			"Tenant",
			"Tenant",
			"Users",
		}
		for _, candidate := range parentRelationFieldCandidates {
			field := childFieldsValue.FieldByName(candidate)
			if !field.IsValid() || !field.CanSet() || field.Kind() != reflect.Bool {
				continue
			}
			field.SetBool(true)
			break
		}

		parentIDSet := make(map[types.IdentityUUID]bool, len(results))
		parentIDs := make([]types.IdentityUUID, 0, len(results))
		for _, result := range results {
			if result == nil {
				continue
			}
			resultID, ok := tenantUUIDValue(result.Id)
			if !ok {
				continue
			}
			if !parentIDSet[resultID] {
				parentIDSet[resultID] = true
				parentIDs = append(parentIDs, resultID)
			}
		}
		if len(parentIDs) > 0 {
			// Get repository for related type
			var repo *TenantUserRepository
			if r.tx != nil {
				txDB := r.txDB
				if txDB == nil {
					txDB = r.db
				}
				repo = &TenantUserRepository{tx: r.tx, txDB: txDB}
			} else if r.db != nil {
				repo = r.db.TenantUser
			} else if r.txDB != nil {
				repo = r.txDB.TenantUser
			} else {
				return nil, 0, fmt.Errorf("no database connection available for users hydration")
			}

			childFilter := &TenantUserFilter{}
			childFilterValue := reflect.ValueOf(childFilter).Elem()
			filterFieldCandidates := []string{
				"TenantID",
				"TenantID",
				"UsersID",
			}
			var selectedFilterField string
			filterSet := false
			for _, candidate := range filterFieldCandidates {
				field := childFilterValue.FieldByName(candidate)
				if !field.IsValid() || !field.CanSet() {
					continue
				}
				field.Set(reflect.ValueOf(&UUIDFilter{
					In: parentIDs,
				}))
				selectedFilterField = candidate
				filterSet = true
				break
			}
			if !filterSet {
				return nil, 0, fmt.Errorf("failed to locate hasMany FK filter for Tenant.users")
			}

			// The other recursion point: these children hydrate their own relations.
			// This block only runs on an explicit nested selection, so the cycle half
			// of the guard does not apply and only the depth cap can refuse it.
			children := []*types.TenantUser{}
			if hydrationCtx, allowed := enterRelationHydration(ctx, "Tenant", "users", "TenantUser", false); allowed {
				fetched, _, findErr := repo.FindMany(hydrationCtx, childFilter, &TenantUserFindOptions{
					Fields: childFields,
					Limit:  1000000,
				})
				if findErr != nil {
					return nil, 0, fmt.Errorf("failed to batch fetch users: %w", findErr)
				}
				children = fetched
			}

			parentFieldCandidates := []string{
				"Tenant",
				strings.TrimSuffix(selectedFilterField, "ID"),
				"Tenant",
				"Users",
			}
			childrenByParentID := make(map[types.IdentityUUID][]types.TenantUser, len(parentIDs))
			for _, child := range children {
				if child == nil {
					continue
				}
				childValue := reflect.ValueOf(child)
				if childValue.Kind() == reflect.Ptr {
					if childValue.IsNil() {
						continue
					}
					childValue = childValue.Elem()
				}
				if !childValue.IsValid() || childValue.Kind() != reflect.Struct {
					continue
				}

				var parentID types.IdentityUUID
				foundParent := false
				for _, candidate := range parentFieldCandidates {
					parentField := childValue.FieldByName(candidate)
					if !parentField.IsValid() {
						continue
					}
					if parentField.Kind() == reflect.Ptr {
						if parentField.IsNil() {
							continue
						}
						parentField = parentField.Elem()
					}
					if !parentField.IsValid() || parentField.Kind() != reflect.Struct {
						continue
					}
					idField := parentField.FieldByName("Id")
					if !idField.IsValid() || !idField.CanInterface() {
						continue
					}
					id, ok := tenantUUIDValue(idField.Interface())
					if !ok {
						continue
					}
					parentID = id
					foundParent = true
					break
				}
				if !foundParent {
					continue
				}

				childrenByParentID[parentID] = append(childrenByParentID[parentID], *child)
			}

			for _, result := range results {
				if result == nil {
					continue
				}
				resultID, ok := tenantUUIDValue(result.Id)
				if !ok {
					continue
				}
				result.Users = childrenByParentID[resultID]
			}
		}
	}

	return results, totalCount, nil
}

